import json
import sqlite3
import time
from datetime import datetime, timezone
from pathlib import Path


def now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def write_json(path: Path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding="utf-8")
    # Windows readers may briefly deny replace while reading an evidence file.
    # Preserve atomic publication, but allow the reader to release its handle.
    deadline = time.monotonic() + 2
    while True:
        try:
            temporary.replace(path)
            break
        except PermissionError:
            if time.monotonic() >= deadline:
                raise
            time.sleep(0.01)


class Store:
    def __init__(self, home: Path):
        self.home = home.resolve()
        self.home.mkdir(parents=True, exist_ok=True)
        self.db = self.home / "index.sqlite3"
        with self.connect() as con:
            con.execute("CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, payload TEXT NOT NULL)")

    def connect(self):
        return sqlite3.connect(self.db, timeout=20)

    def put(self, job):
        with self.connect() as con:
            con.execute("INSERT INTO jobs VALUES (?, ?) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload",
                        (job["id"], json.dumps(job, ensure_ascii=False)))

    def get(self, job_id):
        with self.connect() as con:
            row = con.execute("SELECT payload FROM jobs WHERE id=?", (job_id,)).fetchone()
        if not row:
            raise KeyError(job_id)
        return json.loads(row[0])

    def list(self):
        with self.connect() as con:
            rows = con.execute("SELECT payload FROM jobs ORDER BY rowid DESC LIMIT 200").fetchall()
        return [json.loads(row[0]) for row in rows]

    def folder(self, job_id):
        self.get(job_id)
        return self.home / "jobs" / job_id

    def findings(self, job_id):
        folder = self.folder(job_id) / "findings"
        return [json.loads(p.read_text(encoding="utf-8")) for p in sorted(folder.glob("*/finding.json"))]
"""Generic deterministic boundary/JSON/byte mutations; no target-specific keys."""
from __future__ import annotations

import copy
import json
import random
from collections.abc import Iterator
from itertools import chain


def structured(data: bytes) -> Iterator[bytes]:
    try:
        obj = json.loads(data)
    except (ValueError, UnicodeError, RecursionError):
        return

    def encode(value):
        return json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode("utf-8")

    yield encode(obj)
    if isinstance(obj, dict):
        for key in obj:
            other = copy.deepcopy(obj)
            del other[key]
            yield encode(other)
        for key, value in obj.items():
            replacements = [None, "", [], {}]
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                replacements = [0, -1, 1, 2147483647, -2147483648] + replacements
            elif isinstance(value, str):
                replacements += ["A" * 256, "\x00", "中文🙂"]
            for replacement in replacements:
                other = copy.deepcopy(obj)
                other[key] = replacement
                yield encode(other)
    elif isinstance(obj, list):
        yield b"[]"
        for i in range(min(len(obj), 64)):
            yield encode(obj[:i] + obj[i + 1:])


def generate(seeds: list[bytes], max_cases: int, random_seed: int,
             max_bytes: int) -> Iterator[tuple[str, bytes]]:
    seen = set()
    count = 0
    # Generate lazily: a small case budget must not first materialize every
    # mutation of a large structured input.
    initial = chain(
        (("seed", data) for data in seeds),
        (("boundary", data) for data in [b"", b"\n", b"{}", b"[]", b"null", b"\xff", b"A" * min(4096, max_bytes)]),
        (("json-structure", value) for data in seeds for value in structured(data)),
    )
    for strategy, data in initial:
        if len(data) > max_bytes or data in seen:
            continue
        seen.add(data)
        yield strategy, data
        count += 1
        if count >= max_cases:
            return
    rng = random.Random(random_seed)
    attempts = 0
    while count < max_cases and attempts < max_cases * 30:
        attempts += 1
        original = rng.choice(seeds)
        pos = rng.randrange(len(original) + 1)
        end = min(len(original), pos + rng.randint(1, 16))
        operation = rng.randrange(5)
        if operation == 0:
            data = original[:pos] + original[end:]
        elif operation == 1:
            data = original[:pos] + rng.randbytes(rng.randint(1, 16)) + original[pos:]
        elif operation == 2:
            data = original[:pos] + rng.choice([b"0", b"-1", b"null", b"[]", b"\x00"]) + original[end:]
        elif operation == 3:
            data = original[:pos] + original[pos:end] * rng.randint(2, 8) + original[end:]
        else:
            data = original[:pos] + rng.choice(seeds)
        data = data[:max_bytes]
        if data in seen:
            continue
        seen.add(data)
        yield "byte-mutation", data
        count += 1
